// Exact official score calculator
// 1. Cells with '...' (omitted/undefined) are NEVER selected.
// 2. Values falling between thresholds receive the lower score tier (no linear interpolation).
export function calculateOfficialAftScore(
  eventCode: string,
  rawVal: number,
  ageGroup: string
): number {
  if (isNaN(rawVal) || rawVal <= 0) return 0;
  const ageKey = normalizeAgeGroup(ageGroup);

  let table: Record<number, Partial<Record<AgeGroupKey, number>>>;
  let isHigherBetter = true;

  switch (eventCode) {
    case 'MDL':
      table = MDL_MALE_TABLE;
      isHigherBetter = true;
      break;
    case 'HRP':
      table = HRP_MALE_TABLE;
      isHigherBetter = true;
      break;
    case 'SDC':
      table = SDC_MALE_TABLE;
      isHigherBetter = false;
      break;
    case 'PLK':
      table = PLK_MALE_TABLE;
      isHigherBetter = true;
      break;
    case '2MR':
      table = TWO_MILE_RUN_MALE_TABLE;
      isHigherBetter = false;
      break;
    default:
      return 0;
  }

  // Build list of valid, explicitly defined point breakpoints for this specific age group
  // Strictly sorted descending (100 down to 0)
  const validTiers: { point: number; threshold: number }[] = [];
  const points = Object.keys(table).map(Number).sort((a, b) => b - a);

  for (const pt of points) {
    const threshold = table[pt]?.[ageKey];
    if (threshold !== undefined) {
      validTiers.push({ point: pt, threshold });
    }
  }

  if (validTiers.length === 0) return 0;

  // Search from top (100) to bottom (0).
  // The first tier that satisfies the threshold condition is awarded.
  // Intermediate values that did not meet a higher tier fall through to the lower tier.
  for (const tier of validTiers) {
    if (isHigherBetter) {
      if (rawVal >= tier.threshold) {
        return tier.point;
      }
    } else {
      // Lower time is better
      if (rawVal <= tier.threshold) {
        return tier.point;
      }
    }
  }

  return 0;
}

// Get the exact minimum passing standard (60 pts) from the official table
export function getOfficialPassingStandard(
  eventCode: string,
  ageGroup: string
): string {
  const ageKey = normalizeAgeGroup(ageGroup);
  switch (eventCode) {
    case 'MDL':
      return `${MDL_MALE_TABLE[60]?.[ageKey] ?? ''}`;
    case 'HRP':
      return `${HRP_MALE_TABLE[60]?.[ageKey] ?? ''}`;
    case 'SDC':
      return SDC_MALE_TABLE[60]?.[ageKey] !== undefined ? formatSecondsToTime(SDC_MALE_TABLE[60]![ageKey]!) : '';
    case 'PLK':
      return PLK_MALE_TABLE[60]?.[ageKey] !== undefined ? formatSecondsToTime(PLK_MALE_TABLE[60]![ageKey]!) : '';
    case '2MR':
      return TWO_MILE_RUN_MALE_TABLE[60]?.[ageKey] !== undefined ? formatSecondsToTime(TWO_MILE_RUN_MALE_TABLE[60]![ageKey]!) : '';
    default:
      return '';
  }
}

// Format seconds to mm:ss
export function formatSecondsToTime(totalSecs: number): string {
  const mins = Math.floor(totalSecs / 60);
  const secs = totalSecs % 60;
  return `${mins}:${secs.toString().padStart(2, '0')}`;
}
